import asyncio
import json
from typing import Any, Dict, List, Optional

import aiohttp
import structlog
from pydantic import BaseModel, StrictBool, StrictStr, ValidationError

from rasa.builder.copilot.mcp_server.constants import (
    LLM_MESSAGE_CONTENT,
    LLM_ROLE,
    LLM_ROLE_ASSISTANT,
    LLM_ROLE_SYSTEM,
    LLM_ROLE_USER,
    SIM_EVAL_LLM_MAX_ATTEMPTS,
    SIM_EVAL_RETRY_BACKOFF_FACTOR,
    SIMULATOR_MAX_TURNS,
)
from rasa.builder.copilot.mcp_server.prompts.prompt_loader import (
    copilot_jinja_env,
    get_simulated_user_system_prompt_template,
)
from rasa.builder.copilot.mcp_server.tools.scenario import Scenario
from rasa.shared.providers.llm.llm_client import LLMClient
from rasa.shared.utils.llm import (
    get_model_and_provider,
    supports_json_response_format,
    supports_response_schema,
)


class SimulatedUserReply(BaseModel):
    """Validated JSON payload returned by the LLM user simulator."""

    message: StrictStr
    done: StrictBool


# Keys for turns and transcript
_TURN = "turn"
_BOT = "bot"
_USER = "user"

# Turn prompts
_SIMULATOR_OPENING_TURN_PROMPT = (
    "(The conversation is starting. Send your opening message as the user.)"
)
_SIMULATOR_TURN_PROMPT = "Bot: {bot_text}\n\nYour reply (as the user):"

# Timeout for sending messages to the Rasa server
_SEND_MESSAGE_TIMEOUT = 30.0

structlogger = structlog.get_logger()


async def run_text_simulation(
    scenario: Scenario,
    llm_client: LLMClient,
    session: aiohttp.ClientSession,
    conversation_id: str,
    rasa_url: str,
    prompt_template: str = get_simulated_user_system_prompt_template(),
    max_turns: int = SIMULATOR_MAX_TURNS,
) -> List[Dict[str, Any]]:
    """Drive the text user/bot turn loop and return simulated turns.

    Owns the LLM conversation history: builds the system prompt from
    ``scenario``, appends user and assistant messages each turn, and
    selects the correct turn prompt (opening vs. follow-up). Stops
    when the simulated user sets ``done=True``, sends an empty
    message, the bot returns no response, or ``max_turns`` is reached.

    The caller owns the wider HTTP lifecycle: creating the
    conversation id, opening the ``aiohttp.ClientSession``, injecting
    initial slots, and fetching the tracker afterward.

    Args:
        scenario: ``Scenario`` model instance used to build the
            simulator system prompt from its
            ``simulation_context`` attribute.
        llm_client: LLM client driving the simulated user.
        session: Open ``aiohttp.ClientSession`` used to send
            messages to the Rasa server.
        conversation_id: Rasa conversation (sender) id.
        rasa_url: Base URL of the running Rasa server.
        prompt_template: LLM system prompt template for the user simulator. It will be
            rendered with the scenario's ``simulation_context``.
        max_turns: Maximum number of user/bot turns before stopping.

    Returns:
        A list of turn dicts, each with ``turn``, ``user``, and
        ``bot`` keys.
    """
    llm_history: List[Dict[str, str]] = [
        {
            LLM_ROLE: LLM_ROLE_SYSTEM,
            LLM_MESSAGE_CONTENT: _build_simulated_user_system_prompt(
                scenario, prompt_template
            ),
        }
    ]
    bot_messages: List[str] = []
    turns: List[Dict[str, Any]] = []
    completion_kwargs = _user_simulator_completion_kwargs(
        llm_client, conversation_id=conversation_id
    )

    for turn_num in range(max_turns):
        if bot_messages:
            bot_text = " ".join(bot_messages)
            prompt = _SIMULATOR_TURN_PROMPT.format(
                bot_text=bot_text,
            )
        else:
            prompt = _SIMULATOR_OPENING_TURN_PROMPT
        llm_history.append({LLM_ROLE: LLM_ROLE_USER, LLM_MESSAGE_CONTENT: prompt})

        reply = await _generate_user_message(
            llm_client,
            llm_history,
            completion_kwargs=completion_kwargs,
            conversation_id=conversation_id,
        )

        llm_history.append(
            {LLM_ROLE: LLM_ROLE_ASSISTANT, LLM_MESSAGE_CONTENT: reply.message}
        )

        user_message = reply.message
        if not user_message.strip():
            break

        bot_messages = await _send_message(
            session, conversation_id, user_message, rasa_url
        )
        turns.append(
            {
                _TURN: turn_num + 1,
                _USER: user_message,
                _BOT: bot_messages,
            }
        )

        if reply.done or not bot_messages:
            break

    return turns


async def _send_message(
    session: aiohttp.ClientSession,
    conversation_id: str,
    text: str,
    rasa_url: str,
    *,
    max_attempts: int = SIM_EVAL_LLM_MAX_ATTEMPTS,
    timeout: float = _SEND_MESSAGE_TIMEOUT,
) -> List[str]:
    """Send a user message to the Rasa server and return bot reply texts.

    Retries on HTTP errors, connection failures, and timeouts using a linear backoff.

    Args:
        session: Open ``aiohttp.ClientSession``.
        conversation_id: Rasa conversation (sender) id.
        text: User message text.
        rasa_url: Base URL of the running Rasa server.
        max_attempts: Total tries before giving up.
        timeout: Per-request timeout in seconds.

    Returns:
        List of bot response strings (may be empty when the bot
        responds with non-text payloads only).

    Raises:
        RuntimeError: when all retry attempts are exhausted.
    """
    url = f"{rasa_url.rstrip('/')}/webhooks/rest/webhook"
    payload = {
        "sender": conversation_id,
        "message": text,
        "metadata": {"is_simulation": True},
    }
    last_error: Optional[str] = None

    for attempt in range(1, max_attempts + 1):
        try:
            async with session.post(
                url,
                json=payload,
                timeout=aiohttp.ClientTimeout(total=timeout),
            ) as resp:
                resp.raise_for_status()
                data = await resp.json()
                return [msg["text"] for msg in data if msg.get("text")]
        except Exception as exc:
            last_error = repr(exc)
            structlogger.warning(
                "rasa.simulation.send_message.failed",
                attempt=attempt,
                max_attempts=max_attempts,
                error=last_error,
            )

        if attempt < max_attempts:
            await asyncio.sleep(SIM_EVAL_RETRY_BACKOFF_FACTOR * attempt)

    structlogger.error(
        "rasa.simulation.send_message.exhausted",
        max_attempts=max_attempts,
        error=last_error,
    )
    raise RuntimeError(
        f"send_message failed after {max_attempts} " f"attempts: {last_error}"
    )


def _build_simulated_user_system_prompt(
    scenario: Scenario, prompt_template: str
) -> str:
    """Build the system prompt for the LLM user simulator."""
    return (
        copilot_jinja_env()
        .from_string(prompt_template)
        .render(
            simulation_context=scenario.simulation_context,
        )
    )


def _user_simulator_completion_kwargs(
    llm_client: LLMClient,
    *,
    conversation_id: str,
) -> Dict[str, Any]:
    """Return per-call LLM kwargs for the user simulator.

    Prefer provider-side schema enforcement when available. Fall back
    to plain JSON-object mode for models that support syntactic JSON
    but not schemas. Capabilities are model-level, not turn-level, so
    callers should compute these kwargs once per simulation and reuse
    them for every turn.
    """
    model, _ = get_model_and_provider(llm_client)
    schema_supported = supports_response_schema(llm_client)
    if schema_supported:
        structlogger.debug(
            "rasa.simulation.user_simulator.structured_output",
            conversation_id=conversation_id,
            mode="pydantic_schema",
            model=model,
        )
        return {"response_format": SimulatedUserReply}

    json_mode_supported = supports_json_response_format(llm_client)
    structlogger.debug(
        "rasa.simulation.user_simulator.structured_output",
        conversation_id=conversation_id,
        mode="json_object" if json_mode_supported else "prompt_only",
        model=model,
    )
    if json_mode_supported:
        return {"response_format": {"type": "json_object"}}
    return {}


def _validate_simulator_reply(
    payload: Any,
) -> Optional[SimulatedUserReply]:
    """Validate a parsed simulator payload without coercing types."""
    if not isinstance(payload, dict):
        return None
    try:
        return SimulatedUserReply.model_validate(payload)
    except ValidationError:
        return None


def _parse_simulator_response(
    raw: str,
) -> Optional[SimulatedUserReply]:
    """Parse the user-simulator's JSON reply, tolerant of trailing junk.

    Tries strict ``json.loads`` first, then falls back to
    ``raw_decode`` which ignores trailing garbage after the first
    valid JSON object. Returns ``None`` when neither strategy
    produces a valid ``SimulatedUserReply``, signaling the caller
    to retry.
    """
    if not raw:
        return None

    try:
        return _validate_simulator_reply(json.loads(raw))
    except json.JSONDecodeError:
        pass

    start = raw.find("{")
    if start >= 0:
        try:
            obj, _ = json.JSONDecoder().raw_decode(raw[start:])
            return _validate_simulator_reply(obj)
        except json.JSONDecodeError:
            pass

    return None


async def _generate_user_message(
    llm_client: LLMClient,
    messages: List[Dict[str, str]],
    completion_kwargs: Optional[Dict[str, Any]] = None,
    *,
    conversation_id: str,
    max_attempts: int = SIM_EVAL_LLM_MAX_ATTEMPTS,
) -> SimulatedUserReply:
    """Call the LLM to get simulated user message and return a validated reply.

    This function does **not** mutate ``messages``; the caller is
    responsible for appending the reply to the conversation history
    so it retains full control over state.

    Args:
        llm_client: LLM client used to generate the simulated user
            message.
        messages: Full chat-completion message list the caller has
            already assembled (system prompt, prior turns, and the
            latest user-prompt entry).
        completion_kwargs: Extra keyword arguments forwarded to
            ``llm_client.acompletion`` (e.g. ``response_format``).
            Should be computed once via
            ``_user_simulator_completion_kwargs`` and reused for
            every turn.
        max_attempts: Number of retries on LLM call failures or
            unparseable responses before giving up.

    Returns:
        A validated ``SimulatedUserReply`` with ``.message`` and
        ``.done`` fields.

    Raises:
        RuntimeError: after all retry attempts are exhausted.
    """
    extra_kwargs = completion_kwargs or {}
    structlogger.debug(
        "rasa.simulation.user_simulator.prompt",
        conversation_id=conversation_id,
        messages=messages,
    )
    last_error: Optional[str] = None
    for attempt in range(1, max_attempts + 1):
        try:
            response = await llm_client.acompletion(messages, **extra_kwargs)
            raw = response.choices[0].strip()
            parsed = _parse_simulator_response(raw)
            if parsed is not None:
                return parsed
            last_error = f"could not parse simulator reply: {raw!r}"
            structlogger.debug(
                "rasa.simulation.user_simulator.parse_failed",
                conversation_id=conversation_id,
                attempt=attempt,
                max_attempts=max_attempts,
                raw=raw,
            )
        except Exception as exc:
            last_error = repr(exc)
            structlogger.warning(
                "rasa.simulation.user_simulator.call_failed",
                conversation_id=conversation_id,
                attempt=attempt,
                max_attempts=max_attempts,
                error=last_error,
            )

        if attempt < max_attempts:
            await asyncio.sleep(SIM_EVAL_RETRY_BACKOFF_FACTOR * attempt)

    structlogger.error(
        "rasa.simulation.user_simulator.exhausted",
        conversation_id=conversation_id,
        max_attempts=max_attempts,
        error=last_error,
    )
    raise RuntimeError(
        f"user simulator failed after {max_attempts} " f"attempts: {last_error}"
    )
